// Block (composition) — a full-width secondary section navigation.
import type { Ref } from "react";
import { Link } from "../components/Link";
import { Separator } from "../components/Separator";
import { Stack } from "../layouts/Stack";
import "./SubNav.css";

export interface SubNavProps {
  /**
   * Page-navigation prominence. Size follows the Blocks' medium/large vocabulary rather than
   * adding a visual variant axis: large promotes sibling-page names to headlines, omits the
   * separator and scrolls horizontally. Medium preserves the compact, wrapping navigation.
   *
   * @default "medium"
   */
  size?: "medium" | "large";
  items: { label: string; href: string }[];
  activeHref?: string;
  /** Show a separator beneath medium navigation; large never draws one. */
  showSeparator?: boolean;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function SubNav({
  size = "medium",
  items,
  activeHref,
  showSeparator = true,
  className,
  ref,
}: SubNavProps) {
  // CONTRASTIVE: sibling-page names sit below a page headline-medium; compact names stay labels.
  const typeClass = size === "large" ? "sd-type-headline-small" : "sd-type-label-medium";
  // The large row lends its weight too: Link's relative current weight resolves against its parent.
  const links = (
    <Stack
      as={size === "large" ? "ul" : "div"}
      direction="row"
      gap="medium"
      align="center"
      wrap={size !== "large"}
      data-size={size}
      className={size === "large" ? `sd-subnav__links ${typeClass}` : "sd-subnav__links"}
    >
      {items.map((item, index) => {
        const link = (
          <Link
            key={`${item.label}-${index}`}
            href={item.href}
            aria-current={activeHref === item.href ? "page" : undefined}
            variant={size === "large" ? "subtle" : "quiet"}
            className={typeClass}
          >
            {item.label}
          </Link>
        );
        return size === "large" ? (
          <li key={`${item.label}-${index}`} className="sd-subnav__item">{link}</li>
        ) : link;
      })}
    </Stack>
  );

  return (
    <nav
      ref={ref}
      aria-label="Secondary"
      data-size={size}
      className={className ? `sd-subnav ${className}` : "sd-subnav"}
    >
      {links}
      {size === "medium" && showSeparator && <Separator className="sd-subnav__separator" />}
    </nav>
  );
}

/* SubNav.css — full-width secondary navigation arrangement only. */
.sd-subnav {
  width: 100%;
}

.sd-subnav__links {
  width: 100%;
}

.sd-subnav__separator {
  margin-top: var(--sd-space-small);
}

.sd-subnav__links[data-size="large"] {
  /* Compensated room for focus rings; tabbing to each anchor scrolls it into view. */
  width: calc(100% + 2 * var(--sd-state-focus-ring-width));
  margin: calc(-1 * var(--sd-state-focus-ring-width));
  padding: var(--sd-state-focus-ring-width);
  list-style: none;
  overflow-x: auto;
}

.sd-subnav__item {
  flex: none;
  white-space: nowrap;
}
